begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email) values ('24000000-0000-4000-8000-000000000001','zone-a@example.invalid'),('24000000-0000-4000-8000-000000000002','zone-b@example.invalid'),('24000000-0000-4000-8000-000000000003','zone-c@example.invalid');
insert into public.households(id,name) values ('24000100-0000-4000-8000-000000000001','Timezone home'),('24000100-0000-4000-8000-000000000002','Other home');
insert into public.household_members(household_id,user_id,display_name) values ('24000100-0000-4000-8000-000000000001','24000000-0000-4000-8000-000000000001','A'),('24000100-0000-4000-8000-000000000001','24000000-0000-4000-8000-000000000002','B'),('24000100-0000-4000-8000-000000000002','24000000-0000-4000-8000-000000000003','C');
select ok(has_function_privilege('authenticated','private.is_supported_calendar_time_zone(text)','EXECUTE'),'authenticated checks can execute the validator');
select ok(not has_function_privilege('anon','private.is_supported_calendar_time_zone(text)','EXECUTE'),'anonymous validator execution is not granted');
select is((select provolatile::text from pg_proc where oid='private.is_supported_calendar_time_zone(text)'::regprocedure),'s','catalog-backed validator is stable rather than immutable');
select ok(not (select prosecdef from pg_proc where oid='private.is_supported_calendar_time_zone(text)'::regprocedure),'validator does not elevate privileges');
select ok((select convalidated from pg_constraint where conname='calendar_events_supported_time_zone'),'calendar timezone constraint is validated');
select ok((select convalidated from pg_constraint where conname='trip_bookings_supported_time_zone'),'booking start timezone constraint is validated');
select ok((select convalidated from pg_constraint where conname='trip_bookings_supported_end_time_zone'),'booking end timezone constraint is validated');
set local role authenticated;
select set_config('request.jwt.claim.sub','24000000-0000-4000-8000-000000000001',true);
select ok(private.is_supported_calendar_time_zone(zone_name),'recognizes named zone '||zone_name) from unnest(array['UTC','Europe/Zurich','America/New_York','US/Eastern','Etc/GMT+2','eUrOpE/zUrIcH']) zone(zone_name);
select ok(not private.is_supported_calendar_time_zone(zone_name),'rejects unknown, numeric or wildcard zone '||coalesce(zone_name,'NULL')) from unnest(array['+02:00','-05:00','0200','Mars/Olympus','Custom/Fixed','Europe/%','Europe/Zur_ch',' Europe/Zurich ',null]) zone(zone_name);
insert into public.household_projects(id,household_id,kind,title) values ('24000200-0000-4000-8000-000000000001','24000100-0000-4000-8000-000000000001','trip','Across time zones');
select lives_ok(format($cmd$insert into public.calendar_events(household_id,title,starts_at,ends_at,time_zone) values ('24000100-0000-4000-8000-000000000001','Named event','2026-10-01T08:00:00Z','2026-10-01T09:00:00Z',%L)$cmd$,zone_name),'calendar accepts '||zone_name) from unnest(array['UTC','Europe/Zurich','US/Eastern','europe/zurich']) zone(zone_name);
insert into public.calendar_events(id,household_id,title,starts_at,ends_at,time_zone) values ('24000300-0000-4000-8000-000000000001','24000100-0000-4000-8000-000000000001','Calendar reference','2026-10-01T08:00:00Z','2026-10-01T09:00:00Z','UTC');
insert into public.trip_bookings(id,household_id,project_id,title,kind,starts_at,ends_at,time_zone,end_time_zone) values ('24000400-0000-4000-8000-000000000001','24000100-0000-4000-8000-000000000001','24000200-0000-4000-8000-000000000001','Zurich to New York','flight','2026-10-01T08:00:00Z','2026-10-01T16:00:00Z','Europe/Zurich','America/New_York');
select is((select end_time_zone from public.trip_bookings where id='24000400-0000-4000-8000-000000000001'),'America/New_York','flight arrival keeps its own timezone');
select lives_ok(format($cmd$insert into public.trip_bookings(household_id,project_id,title,kind,time_zone,end_time_zone) values ('24000100-0000-4000-8000-000000000001','24000200-0000-4000-8000-000000000001','Named booking','flight',%L,%L)$cmd$,zone_name,zone_name),'both booking zones accept '||zone_name) from unnest(array['UTC','US/Eastern','europe/zurich']) zone(zone_name);
select throws_ok(format($cmd$insert into public.calendar_events(household_id,title,starts_at,ends_at,time_zone) values ('24000100-0000-4000-8000-000000000001','Named event','2026-10-01T08:00:00Z','2026-10-01T09:00:00Z',%L)$cmd$,zone_name),'23514',null,'calendar_events.time_zone rejects invalid insert '||zone_name) from unnest(array['+02:00','-05:00','Mars/Olympus','Custom/Fixed','Europe/%','Europe/Zur_ch',' Europe/Zurich ']) zone(zone_name);
select throws_ok(format($cmd$update public.calendar_events set time_zone=%L where id='24000300-0000-4000-8000-000000000001'$cmd$,zone_name),'23514',null,'calendar_events.time_zone rejects invalid update '||zone_name) from unnest(array['+02:00','-05:00','Mars/Olympus','Custom/Fixed','Europe/%','Europe/Zur_ch',' Europe/Zurich ']) zone(zone_name);
select lives_ok($cmd$update public.calendar_events set time_zone='eUrOpE/zUrIcH' where id='24000300-0000-4000-8000-000000000001'$cmd$,'calendar_events.time_zone accepts case-insensitive exact alias on update');
select is((select time_zone from public.calendar_events where id='24000300-0000-4000-8000-000000000001'),'eUrOpE/zUrIcH','valid spelling is preserved for calendar_events.time_zone');
select throws_ok(format($cmd$insert into public.trip_bookings(household_id,project_id,title,kind,time_zone,end_time_zone) values ('24000100-0000-4000-8000-000000000001','24000200-0000-4000-8000-000000000001','Named booking','flight',%L,'UTC')$cmd$,zone_name),'23514',null,'trip_bookings.time_zone rejects invalid insert '||zone_name) from unnest(array['+02:00','-05:00','Mars/Olympus','Custom/Fixed','Europe/%','Europe/Zur_ch',' Europe/Zurich ']) zone(zone_name);
select throws_ok(format($cmd$update public.trip_bookings set time_zone=%L where id='24000400-0000-4000-8000-000000000001'$cmd$,zone_name),'23514',null,'trip_bookings.time_zone rejects invalid update '||zone_name) from unnest(array['+02:00','-05:00','Mars/Olympus','Custom/Fixed','Europe/%','Europe/Zur_ch',' Europe/Zurich ']) zone(zone_name);
select lives_ok($cmd$update public.trip_bookings set time_zone='eUrOpE/zUrIcH' where id='24000400-0000-4000-8000-000000000001'$cmd$,'trip_bookings.time_zone accepts case-insensitive exact alias on update');
select is((select time_zone from public.trip_bookings where id='24000400-0000-4000-8000-000000000001'),'eUrOpE/zUrIcH','valid spelling is preserved for trip_bookings.time_zone');
select throws_ok(format($cmd$insert into public.trip_bookings(household_id,project_id,title,kind,time_zone,end_time_zone) values ('24000100-0000-4000-8000-000000000001','24000200-0000-4000-8000-000000000001','Named booking','flight','UTC',%L)$cmd$,zone_name),'23514',null,'trip_bookings.end_time_zone rejects invalid insert '||zone_name) from unnest(array['+02:00','-05:00','Mars/Olympus','Custom/Fixed','Europe/%','Europe/Zur_ch',' Europe/Zurich ']) zone(zone_name);
select throws_ok(format($cmd$update public.trip_bookings set end_time_zone=%L where id='24000400-0000-4000-8000-000000000001'$cmd$,zone_name),'23514',null,'trip_bookings.end_time_zone rejects invalid update '||zone_name) from unnest(array['+02:00','-05:00','Mars/Olympus','Custom/Fixed','Europe/%','Europe/Zur_ch',' Europe/Zurich ']) zone(zone_name);
select lives_ok($cmd$update public.trip_bookings set end_time_zone='eUrOpE/zUrIcH' where id='24000400-0000-4000-8000-000000000001'$cmd$,'trip_bookings.end_time_zone accepts case-insensitive exact alias on update');
select is((select end_time_zone from public.trip_bookings where id='24000400-0000-4000-8000-000000000001'),'eUrOpE/zUrIcH','valid spelling is preserved for trip_bookings.end_time_zone');
select set_config('request.jwt.claim.sub','24000000-0000-4000-8000-000000000002',true);
select lives_ok($cmd$update public.calendar_events set time_zone='UTC' where id='24000300-0000-4000-8000-000000000001'$cmd$,'partner can update calendar timezone');
select lives_ok($cmd$update public.trip_bookings set time_zone='UTC',end_time_zone='US/Eastern' where id='24000400-0000-4000-8000-000000000001'$cmd$,'partner can update both flight zones');
select is((select count(*) from public.financial_events),0::bigint,'timezone writes never create financial obligations');
select set_config('request.jwt.claim.sub','24000000-0000-4000-8000-000000000003',true);
select is((select count(*) from public.calendar_events where household_id='24000100-0000-4000-8000-000000000001'),0::bigint,'outsider cannot read calendar rows');
select is((select count(*) from public.trip_bookings where household_id='24000100-0000-4000-8000-000000000001'),0::bigint,'outsider cannot read booking rows');
with changed as (update public.calendar_events set time_zone='Asia/Tokyo' where id='24000300-0000-4000-8000-000000000001' returning id) select is(count(*),0::bigint,'outsider cannot update calendar timezone') from changed;
with changed as (update public.trip_bookings set time_zone='Asia/Tokyo',end_time_zone='Asia/Tokyo' where id='24000400-0000-4000-8000-000000000001' returning id) select is(count(*),0::bigint,'outsider cannot update booking timezones') from changed;
select throws_ok($cmd$insert into public.calendar_events(household_id,title,starts_at,ends_at,time_zone) values ('24000100-0000-4000-8000-000000000001','Named event','2026-10-01T08:00:00Z','2026-10-01T09:00:00Z','UTC')$cmd$,'42501',null,'outsider cannot insert into the other calendar');
select throws_ok($cmd$insert into public.trip_bookings(household_id,project_id,title,kind,time_zone,end_time_zone) values ('24000100-0000-4000-8000-000000000001','24000200-0000-4000-8000-000000000001','Named booking','flight','UTC','UTC')$cmd$,'42501',null,'outsider cannot insert into the other trip');
reset role;
select is((select count(*) from public.financial_events),0::bigint,'global financial history is untouched');
select * from finish();
rollback;
